          "image": {
            "type": "string",
            "format": "image",
            "title": "图片"
          },
          "position": {
            "type": "position",
            "key": "option",
            "title": "位置",
            "size": {
              "width": 1920,
              "height": 1080
            },
            "default": {
              "x": 579,
              "y": 612
            }
          }
        },
        "required": [
          "image",
          "position"
        ]
      },
